#include \"logic.hpp\"
#include <cassert>
int main() {
    const std::vector<std::vector<int>> input = {{8, 9}, {2, 2}, {1, 2}, {1, 1}, {4, 7}, {5, 6}};
    const auto original = input;
    const std::vector<std::vector<int>> expected = {{1, 2}, {4, 7}, {8, 9}};
    assert(merge_intervals(input) == expected);
    assert(input == original);
    const int low = std::numeric_limits<int>::min();
    const int high = std::numeric_limits<int>::max();
    const std::vector<std::vector<int>> extremes = {{low, high}};
    assert(merge_intervals({{high, high}, {low, 0}, {0, high}}) == extremes);
}
